type Snapshot = {
  readonly demanded: readonly IRow[];
  readonly fetch_result: readonly IRow[];
  readonly live_fetch: readonly IRow[];
  readonly open_fetch: readonly IRow[];
  readonly phase: readonly IRow[];
  readonly poll_due: readonly IRow[];
  readonly scope_done: readonly IRow[];
};

function read_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    demanded: select_rows(seam, `SELECT CASE WHEN json_valid("col1") AND json_type("col1") = 'object' AND json_type("col1", '$.fn') = 'text' AND json_type("col1", '$.args') = 'array' THEN json_extract("col1", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("col1", '$.args')), '') || ')' ELSE "col1" END AS "col1", CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint" FROM "__txt_demanded"`, rel_columns.demanded!, rel_column_types.demanded!),
    fetch_result: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint", CASE WHEN json_valid("col2") AND json_type("col2") = 'object' AND json_type("col2", '$.fn') = 'text' AND json_type("col2", '$.args') = 'array' THEN json_extract("col2", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("col2", '$.args')), '') || ')' ELSE "col2" END AS "col2" FROM "__txt_fetch_result"`, rel_columns.fetch_result!, rel_column_types.fetch_result!),
    live_fetch: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint" FROM "__txt_live_fetch"`, rel_columns.live_fetch!, rel_column_types.live_fetch!),
    open_fetch: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint" FROM "__txt_open_fetch"`, rel_columns.open_fetch!, rel_column_types.open_fetch!),
    phase: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint", CASE WHEN json_valid("col2") AND json_type("col2") = 'object' AND json_type("col2", '$.fn') = 'text' AND json_type("col2", '$.args') = 'array' THEN json_extract("col2", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("col2", '$.args')), '') || ')' ELSE "col2" END AS "col2" FROM "__txt_phase"`, rel_columns.phase!, rel_column_types.phase!),
    poll_due: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint" FROM "__txt_poll_due"`, rel_columns.poll_due!, rel_column_types.poll_due!),
    scope_done: select_rows(seam, `SELECT CASE WHEN json_valid("endpoint") AND json_type("endpoint") = 'object' AND json_type("endpoint", '$.fn') = 'text' AND json_type("endpoint", '$.args') = 'array' THEN json_extract("endpoint", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("endpoint", '$.args')), '') || ')' ELSE "endpoint" END AS "endpoint" FROM "__txt_scope_done"`, rel_columns.scope_done!, rel_column_types.scope_done!),
  });
}

type Snapshots = { readonly decoded: Snapshot; readonly stored: Snapshot };

function read_stored_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    demanded: select_rows(seam, `SELECT "col1", "endpoint" FROM "demanded"`, rel_columns.demanded!, rel_column_types.demanded!),
    fetch_result: select_rows(seam, `SELECT "endpoint", "col2" FROM "fetch_result"`, rel_columns.fetch_result!, rel_column_types.fetch_result!),
    live_fetch: select_rows(seam, `SELECT "endpoint" FROM "live_fetch"`, rel_columns.live_fetch!, rel_column_types.live_fetch!),
    open_fetch: select_rows(seam, `SELECT "endpoint" FROM "open_fetch"`, rel_columns.open_fetch!, rel_column_types.open_fetch!),
    phase: select_rows(seam, `SELECT "endpoint", "col2" FROM "phase"`, rel_columns.phase!, rel_column_types.phase!),
    poll_due: select_rows(seam, `SELECT "endpoint" FROM "poll_due"`, rel_columns.poll_due!, rel_column_types.poll_due!),
    scope_done: select_rows(seam, `SELECT "endpoint" FROM "scope_done"`, rel_columns.scope_done!, rel_column_types.scope_done!),
  });
}

function read_snapshots(seam: ISqlSeam): Observable<Snapshots> {
  return forkJoin({ decoded: read_snapshot(seam), stored: read_stored_snapshot(seam) });
}

